    <?php if (!$xtreampiRecordStream): ?><form class="sc-form" action="record" method="post" data-sc-record-schedule><section class="sc-form-section"><h2>Schedule a channel</h2><div class="sc-form-grid"><label>Channel<input name="stream_id" list="sc-record-stream-options" required placeholder="Search for a stream…"><datalist id="sc-record-stream-options"></datalist></label><label>Start<input type="datetime-local" name="start_date" required></label><label>Minutes<input type="number" name="duration" min="1" required></label></div></section><div class="sc-form-actions"><button class="sc-button sc-button-primary" type="submit">Continue</button></div></form><p class="sc-section-copy">The stream search uses the existing <code>api?action=streamlist</code> endpoint; the controller validates the stream and time window.</p><?php else: ?>
    <form class="sc-form" action="post.php?action=record&amp;referer=archive" method="post" data-sc-record-form><input type="hidden" name="stream_id" value="<?php echo (int) $xtreampiRecordStream['id']; ?>"><input type="hidden" name="start" value="<?php echo (int) ($xtreampiProgramme['start'] ?? 0); ?>"><input type="hidden" name="end" value="<?php echo (int) ($xtreampiProgramme['end'] ?? 0); ?>"><input type="hidden" name="archive" value="<?php echo !empty($xtreampiProgramme['archive']) ? '1' : '0'; ?>"><section class="sc-form-section"><h2><?php echo sc_m_escape($xtreampiRecordStream['stream_display_name'] ?? 'Channel'); ?></h2><p class="sc-section-copy"><?php echo sc_m_escape(($xtreampiProgramme['title'] ?? 'Untitled event')); ?> · <?php echo !empty($xtreampiProgramme['start']) ? date(($rSettings['date_format'] ?? 'Y-m-d') . ' H:i', (int) $xtreampiProgramme['start']) : '—'; ?> to <?php echo !empty($xtreampiProgramme['end']) ? date(($rSettings['date_format'] ?? 'Y-m-d') . ' H:i', (int) $xtreampiProgramme['end']) : '—'; ?></p><div class="sc-form-grid"><label>Event title<input name="title" required value="<?php echo sc_m_escape($xtreampiProgramme['title'] ?? ''); ?>"></label><label>Poster URL<input name="stream_icon" value=""></label><label>Recording server<select name="source_id" required><?php foreach ((array) ($rAvailableServers ?? []) as $xtreampiServerId): $xtreampiServer = $xtreampiServers[$xtreampiServerId] ?? []; ?><option value="<?php echo (int) $xtreampiServerId; ?>"><?php echo sc_m_escape($xtreampiServer['server_name'] ?? $xtreampiServer['server_ip'] ?? ('Server #' . $xtreampiServerId)); ?></option><?php endforeach; ?></select></label><label>Categories<select name="category_id[]" multiple><?php foreach ((array) $xtreampiCategories as $xtreampiCategory): ?><option value="<?php echo (int) ($xtreampiCategory['id'] ?? 0); ?>"><?php echo sc_m_escape($xtreampiCategory['category_name'] ?? ''); ?></option><?php endforeach; ?></select></label><label>Bouquets<select name="bouquets[]" multiple><?php foreach ((array) $xtreampiBouquets as $xtreampiBouquet): ?><option value="<?php echo (int) ($xtreampiBouquet['id'] ?? 0); ?>"><?php echo sc_m_escape($xtreampiBouquet['bouquet_name'] ?? ''); ?></option><?php endforeach; ?></select></label></div><label>Description<textarea name="description" rows="6"><?php echo sc_m_escape($xtreampiProgramme['description'] ?? ''); ?></textarea></label></section><div class="sc-form-actions"><button class="sc-button sc-button-primary" type="submit">Schedule</button></div></form><?php endif; ?>
